144	#[derive(Serialize, Deserialize)]
145	struct PersistedCollection {
146	    name: String,
147	    records: Vec<Record>,
148	}
149	
150	#[derive(Serialize, Deserialize)]
151	struct PersistedVersion {
152	    id: u64,
153	    saved_at: u64,
154	    collections: Vec<PersistedCollection>,
155	}
156	
157	/// `snapshot.json` 的完整内容。
158	#[derive(Serialize, Deserialize)]
159	struct PersistedState {
160	    versions: Vec<PersistedVersion>,
161	    collections: Vec<PersistedCollection>,
162	}
163	
164	struct Inner {
165	    /// 各集合的当前数据；Vec 保存提交顺序。
166	    current: BTreeMap<String, Vec<Record>>,
167	    versions: Vec<VersionSnap>,
168	    next_id: u64,
169	    wal: fs::File,
170	}
171	
172	/// 整个服务的状态。
173	pub struct Store {
174	    inner: Mutex<Inner>,
175	    data_dir: PathBuf,
176	}
177	
178	fn now_ms() -> u64 {
179	    SystemTime::now()
180	        .duration_since(UNIX_EPOCH)
181	        .map(|d| d.as_millis() as u64)
182	        .unwrap_or(0)
183	}
