510	    /// 把当前各集合数据固化为只读版本，返回版本标识与保存时间。
511	    pub fn save_version(&self) -> Result<VersionSummary, String> {
512	        let mut st = self.inner.lock().unwrap();
513	        let id = st.next_id;
514	        let saved_at = now_ms();
515	        let data: HashMap<String, Vec<Record>> = st
516	            .current
517	            .iter()
518	            .map(|(name, records)| (name.clone(), records.clone()))
519	            .collect();
520	        st.versions.push(VersionSnap { id, saved_at, data });
521	        st.next_id += 1;
522	
523	        // 固化完整状态到快照文件，然后清空 WAL（旧提交已包含在快照中）。
524	        persist_state(&self.data_dir, &st)?;
525	        truncate_wal(&mut st.wal, &self.data_dir.join("wal.log"))?;
526	
527	        Ok(VersionSummary { id, saved_at })
528	    }
