530	    /// 查询指定版本内指定集合的全部记录（字段顺序与写入时一致）。
531	    pub fn read_records(
532	        &self,
533	        version_id: u64,
534	        collection: &str,
535	    ) -> Result<Vec<Record>, LookupError> {
536	        let st = self.inner.lock().unwrap();
537	        let version = st
538	            .versions
539	            .iter()
540	            .find(|v| v.id == version_id)
541	            .ok_or(LookupError::VersionNotFound)?;
542	        version
543	            .data
544	            .get(collection)
545	            .cloned()
546	            .ok_or(LookupError::CollectionNotFound)
547	    }
