549	    /// 比较同一集合在两个已保存版本之间的差异。
550	    ///
551	    /// 只读取快照，不生成新版本、不改写任何数据。记录内容比较与写入冲突检测一致：
552	    /// 字段顺序不影响判定，字段名与字段值相同即视为同一条记录。
553	    pub fn diff_versions(
554	        &self,
555	        from: u64,
556	        to: u64,
557	        collection: &str,
558	    ) -> Result<DiffOutcome, DiffError> {
559	        let st = self.inner.lock().unwrap();
560	        let from_v = st
561	            .versions
562	            .iter()
563	            .find(|v| v.id == from)
564	            .ok_or(DiffError::FromVersionNotFound)?;
565	        let to_v = st
566	            .versions
567	            .iter()
568	            .find(|v| v.id == to)
569	            .ok_or(DiffError::ToVersionNotFound)?;
570	        if from > to {
571	            return Err(DiffError::OutOfOrder);
572	        }
573	        let from_recs = from_v
574	            .data
575	            .get(collection)
576	            .ok_or(DiffError::CollectionNotFoundInFrom)?;
577	        let to_recs = to_v
578	            .data
579	            .get(collection)
580	            .ok_or(DiffError::CollectionNotFoundInTo)?;
581	
582	        // BTreeMap 迭代顺序即主键 id 的字节序升序。
583	        let from_map: BTreeMap<&str, &Record> = from_recs
584	            .iter()
585	            .map(|r| (r["id"].as_str().expect("validated record"), r))
586	            .collect();
587	        let to_map: BTreeMap<&str, &Record> = to_recs
588	            .iter()
589	            .map(|r| (r["id"].as_str().expect("validated record"), r))
590	            .collect();
591	
592	        let mut added = Vec::new();
593	        let mut dropped = Vec::new();
594	        let mut changed = Vec::new();
595	        for (id, before) in &from_map {
596	            match to_map.get(id) {
597	                None => added.push((*before).clone()),
598	                Some(after) if **after != **before => changed.push(ChangedRecord {
599	                    before: (*before).clone(),
600	                    after: (*after).clone(),
601	                }),
602	                Some(_) => {}
603	            }
604	        }
605	        for (id, after) in &to_map {
606	            if !from_map.contains_key(id) {
607	                dropped.push((*after).clone());
608	            }
609	        }
610	
611	        Ok(DiffOutcome {
612	            from,
613	            to,
614	            collection: collection.to_string(),
615	            added,
616	            dropped,
617	            changed,
618	        })
619	    }
