678	fn append_wal(wal: &mut fs::File, event: &WalEvent) -> Result<(), String> {
679	    let mut line = serde_json::to_vec(event).map_err(|e| format!("encode wal: {e}"))?;
680	    line.push(b'\n');
681	    wal.write_all(&line)
682	        .and_then(|_| wal.flush())
683	        .and_then(|_| wal.sync_all())
684	        .map_err(|e| format!("wal append: {e}"))
685	}
