761	/// 递归校验字段值：仅允许字符串、整数、布尔、null 与嵌套对象；
762	/// 浮点数与数组一律拒绝。
763	fn validate_value(v: &Value) -> Result<(), String> {
764	    match v {
765	        Value::Null | Value::Bool(_) | Value::String(_) => Ok(()),
766	        Value::Number(n) if n.is_i64() || n.is_u64() => Ok(()),
767	        Value::Number(_) => Err("number must be an integer".to_string()),
768	        Value::Object(map) => {
769	            for (k, child) in map {
770	                validate_value(child).map_err(|e| format!("{k}: {e}"))?;
771	            }
772	            Ok(())
773	        }
774	        Value::Array(_) => Err("arrays are not allowed".to_string()),
775	    }
776	}
