699	#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
700	async fn concurrent_writes_and_snapshots_never_see_half_batches() {
701	    let s = Arc::new(spawn_server().await);
702	    let writers = 8usize;
703	    let batches = 12usize;
704	    let batch_size = 5usize;
705	
706	    let mut handles = Vec::new();
707	    for w in 0..writers {
708	        let addr = s.addr.clone();
709	        handles.push(tokio::spawn(async move {
710	            for b in 0..batches {
711	                let mut recs = String::from("[");
712	                for i in 0..batch_size {
713	                    if i > 0 {
714	                        recs.push(',');
715	                    }
716	                    recs.push_str(&format!(
717	                        "{{\"id\":\"w{w}-b{b}-r{i}\",\"w\":{w},\"b\":{b},\"i\":{i}}}"
718	                    ));
719	                }
720	                recs.push(']');
721	                let payload = format!(r#"{{"records":{recs}}}"#);
722	                let addr2 = addr.clone();
723	                let r = tokio::task::spawn_blocking(move || {
724	                    request(&addr2, "POST", "/collections/items/records", Some(&payload))
725	                })
726	                .await
727	                .unwrap();
728	                assert_eq!(r.status, 200, "batch {w}/{b}: {}", r.body);
729	            }
730	        }));
731	    }
732	
733	    // 并发持续保存快照。
734	    let saver_addr = s.addr.clone();
735	    let saver = tokio::spawn(async move {
736	        let mut saved = Vec::new();
737	        for _ in 0..20 {
738	            let addr2 = saver_addr.clone();
739	            let r = tokio::task::spawn_blocking(move || request(&addr2, "POST", "/versions", None))
740	                .await
741	                .unwrap();
742	            assert_eq!(r.status, 201);
743	            saved.push(r.body["id"].as_u64().unwrap());
744	            tokio::time::sleep(std::time::Duration::from_millis(2)).await;
745	        }
746	        saved
747	    });
748	
749	    for h in handles {
750	        h.await.unwrap();
751	    }
752	    let saved = saver.await.unwrap();
753	
754	    // 每个快照中，任一批次要么完整出现、要么完全不出现。
755	    for vid in saved {
756	        let addr = s.addr.clone();
757	        let r = tokio::task::spawn_blocking(move || {
758	            request(
759	                &addr,
760	                "GET",
761	                &format!("/versions/{vid}/collections/items/records"),
762	                None,
763	            )
764	        })
765	        .await
766	        .unwrap();
767	        assert_eq!(r.status, 200);
768	        // 以 (w,b) 分组计数，每个已出现的批次必须是完整的 batch_size 条。
769	        let mut counts = std::collections::HashMap::new();
770	        for rec in r.body["records"].as_array().unwrap() {
771	            let key = (rec["w"].as_u64().unwrap(), rec["b"].as_u64().unwrap());
772	            *counts.entry(key).or_insert(0u64) += 1;
773	        }
774	        for ((w, b), n) in &counts {
775	            assert_eq!(
776	                *n, batch_size as u64,
777	                "half batch w{w} b{b}: {n}/{batch_size}"
778	            );
779	        }
780	    }
781	
782	    // 最终全部写入均可见（无丢失的已确认批次）。
783	    let r = request(&s.addr, "POST", "/versions", None);
784	    let final_v = r.body["id"].as_u64().unwrap();
785	    let r = request(
786	        &s.addr,
787	        "GET",
788	        &format!("/versions/{final_v}/collections/items/records"),
789	        None,
790	    );
791	    assert_eq!(
792	        r.body["records"].as_array().unwrap().len(),
793	        writers * batches * batch_size
794	    );
795	}
