1117	                    request(&addr2, "POST", "/collections/items/records", Some(&payload))
1118	                })
1119	                .await
1120	                .unwrap();
1121	                assert_eq!(r.status, 200, "{}", r.body);
1122	                assert_eq!(r.body["deleted"].as_u64().unwrap(), chunk.len() as u64);
1123	                assert_eq!(r.body["missing"].as_u64().unwrap(), 0);
1124	            }
1125	        }));
1126	    }
1127	    for w in 0..4usize {
1128	        let addr = s.addr.clone();
1129	        handles.push(tokio::spawn(async move {
1130	            for b in 0..10 {
